using System.Windows;using System.Windows.Controls;using System.Windows.Input;
namespace DanceStudio;
public sealed class FacialLibraryPanel:Expander {
 public static event Action? DragEnded;
 public const string Format="DanceStudio.FacialLibraryItem";readonly FacialLibrary library;readonly ListBox list=new(){MaxHeight=260};readonly TextBox search=new();readonly TextBlock info=new(){TextWrapping=TextWrapping.Wrap};List<FacialLibrary.Item> items=[];
 public FacialLibraryPanel(Action<FacialLibrary.Item> place,FacialLibrary? storage=null){library=storage??new();AllowDrop=true;DragOver+=(_,e)=>{if(!e.Data.GetDataPresent(DataFormats.FileDrop))return;e.Effects=DragDropEffects.Copy;e.Handled=true;};Drop+=(_,e)=>{if(e.Data.GetData(DataFormats.FileDrop) is not string[] files)return;e.Handled=true;var errors=new List<string>();foreach(var file in files)try{if(!file.EndsWith(".facialclip.json",StringComparison.OrdinalIgnoreCase)&&!file.EndsWith(".facialpreset.json",StringComparison.OrdinalIgnoreCase))throw new System.IO.InvalidDataException(UiText.T("dropUnsupported"));ImportFile(file,file.EndsWith(".facialclip.json",StringComparison.OrdinalIgnoreCase));}catch(Exception ex){errors.Add(System.IO.Path.GetFileName(file)+": "+ex.Message);}if(errors.Count>0)MessageBox.Show(string.Join("\n",errors));};Header=new TextBlock{Text=UiText.T("libTitle"),Foreground=StudioTheme.Text};Style=(Style)Application.Current.FindResource(typeof(Expander));IsExpanded=true;Foreground=StudioTheme.Text;HorizontalAlignment=HorizontalAlignment.Stretch;Margin=new Thickness(0,0,0,0);var p=new DockPanel();Content=p;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);p.Children.Add(top);top.Children.Add(search);search.ToolTip=UiText.T("libSearch");search.TextChanged+=(_,_)=>Filter();var actions=new WrapPanel();top.Children.Add(actions);void B(string key,Action action){var b=new Button{Content=UiText.T(key)};actions.Children.Add(b);b.Click+=(_,_)=>{try{action();}catch(Exception e){MessageBox.Show(UiText.Error(e.Message));}};}B("libRemove",()=>{if(list.SelectedItem is FacialLibrary.Item i){library.Remove(i);Reload();}});top.Children.Add(info);list.SetValue(ScrollViewer.HorizontalScrollBarVisibilityProperty,ScrollBarVisibility.Disabled);var itemStyle=new Style(typeof(ListBoxItem),(Style)Application.Current.FindResource(typeof(ListBoxItem)));itemStyle.Setters.Add(new Setter(Control.HorizontalContentAlignmentProperty,HorizontalAlignment.Stretch));list.ItemContainerStyle=itemStyle;var template=new DataTemplate();var text=new FrameworkElementFactory(typeof(TextBlock));text.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding());text.SetBinding(FrameworkElement.ToolTipProperty,new System.Windows.Data.Binding());text.SetValue(TextBlock.TextTrimmingProperty,TextTrimming.CharacterEllipsis);text.SetValue(TextBlock.TextWrappingProperty,TextWrapping.NoWrap);template.VisualTree=text;list.ItemTemplate=template;VirtualizingPanel.SetIsVirtualizing(list,true);p.Children.Add(list);list.MouseDoubleClick+=(_,_)=>{if(list.SelectedItem is FacialLibrary.Item i)try{place(i);}catch(Exception e){MessageBox.Show(UiText.Error(e.Message));}};Point down=new();list.PreviewMouseLeftButtonDown+=(_,e)=>down=e.GetPosition(list);list.PreviewMouseMove+=(_,e)=>{if(e.LeftButton==MouseButtonState.Pressed&&list.SelectedItem is FacialLibrary.Item i&&(e.GetPosition(list)-down).Length>6){try{DragDrop.DoDragDrop(list,new DataObject(Format,i),DragDropEffects.Copy);}finally{DragEnded?.Invoke();}}};Loaded+=(_,_)=>{if(Application.Current.TryFindResource(typeof(Expander)) is Style theme)Style=theme;Reload();};}
 public FacialLibrary.Item ImportFile(string path,bool clip){var i=library.Import(path,clip);Reload();return i;}
 public void Import(bool clip){var d=new Microsoft.Win32.OpenFileDialog{Filter=clip?"Facial clip|*.facialclip.json":"Facial preset|*.facialpreset.json"};if(FaceAssets.RecentDialogPaths.Open(d,Window.GetWindow(this),clip?FaceAssets.RecentDialogPaths.Groups.FacialClip:FaceAssets.RecentDialogPaths.Groups.FacialPreset))ImportFile(d.FileName,clip);}
 void Filter()=>list.ItemsSource=items.Where(i=>i.Name.Contains(search.Text,StringComparison.OrdinalIgnoreCase)).ToList();
 public void Reload(){try{items=library.Read();Filter();info.Text=library.Warnings.Count==0?UiText.T("libTip"):UiText.T("libDamaged")+"\n"+string.Join("\n",library.Warnings.Take(3));}catch(Exception e){info.Text=e.Message;}}
}
